"/**
 * Connect to Wi-Fi with status reporting, network scanning, and timeout safety
 */
void connectWiFi() {
    Serial.printf("[WIFI] Scanning visible 2.4GHz networks...\n");
    WiFi.mode(WIFI_STA);
    WiFi.disconnect(true);
    delay(100);

    int n = WiFi.scanNetworks();
    Serial.printf("[WIFI SCAN] Found %d networks:\n", n);
    bool foundTarget = false;
    for (int i = 0; i < n; ++i) {
        Serial.printf("  [%d] SSID: '%s' | Signal: %d dBm | Ch: %d | Encryption: %s\n",
                      i + 1, WiFi.SSID(i).c_str(), WiFi.RSSI(i), WiFi.channel(i),
                      WiFi.encryptionType(i) == WIFI_AUTH_OPEN ? "Open" : "Secured");
        if (WiFi.SSID(i) == WIFI_SSID) {
            foundTarget = true;
        }
    }

    if (!foundTarget) {
        Serial.printf("[WIFI WARN] Target SSID '%s' was NOT detected in 2.4GHz scan! Make sure hotspot/2.4GHz Wi-Fi is active.\n", WIFI_SSID);
    }

    Serial.printf("[WIFI] Connecting to SSID: '%s' ...\n", WIFI_SSID);
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

    uint8_t timeoutSeconds = 25;
    while (WiFi.status() != WL_CONNECTED && timeoutSeconds > 0) {
        delay(500);
        Serial.print(".");
        timeoutSeconds--;
    }

    if (WiFi.status() == WL_CONNECTED) {
        Serial.println("\n[WIFI] Connected Successfully!");
        Serial.printf("[WIFI] IP Address  : %s\n", WiFi.localIP().toString().c_str());
        Serial.printf("[WIFI] RSSI Signal : %d dBm\n", WiFi.RSSI());
    } else {
        Serial.println("\n[WIFI ERROR] Failed to connect to Wi-Fi. Check SSID and Password.");
    }
}"

